    // protecting the shared counter `acc`.
    let m = Arc::new(Mutex::new(0u64));

    let m1 = Arc::clone(&m);
    let h1 = thread::spawn(move || w1(&m1));

    let m2 = Arc::clone(&m);
    let h2 = thread::spawn(move || w2(&m2));

    // R6/R7: joining both workers guarantees every interleaving
